enum OnboardingEndpoint: String, Codable, Sendable {
  case getOnboarding
  case saveOnboardingDraft
  case completeOnboarding
  case getStrava
  case connectStrava
  case refreshStrava
  case getCatalog
  var path: String {
    switch self {
    case .getOnboarding: "/v1/onboarding"
    case .saveOnboardingDraft: "/v1/onboarding/draft"
